"""Working demo for this book record: full reader + HTML exporter.
Run:  python3 book_demo.py              (prints the whole book)
      python3 book_demo.py 3            (prints chapter 3 only)
      python3 book_demo.py search WORD  (finds WORD across chapters)
      python3 book_demo.py html         (writes book.html)
"""
import json, sys, html as _h

BOOK = {'title': 'Whispers on the old vicarage', 'author': 'Signature original', 'genre': 'Holiday Mysteries', 'chapters': [{'n': 1, 'title': 'Tea and Tidings', 'text': 'The morning Beatrice Nettle found a silver locket on the doorstep of her cottage in the old vicarage, the kettle had just begun to sing. She turned the object over in her hands, frowning, for it plainly belonged to someone — and someone in the old vicarage was missing it badly.\n\nBefore bed she wrote in her journal: Day one. The game is on. Tomorrow I walk the hedgerows and ask the questions no one else will ask. courage in quiet lives — that is what this is about, though no one says so yet.\n\nBy noon the whole of the old vicarage was whispering. Beatrice Nettle listened at the bakery, at the post office, at the garden gate, collecting every whisper like crumbs. Each crumb led back to a silver locket, and a silver locket led somewhere darker.'}, {'n': 2, 'title': 'The Missing Piece', 'text': 'Beatrice Nettle began with the old vicarage itself, walking every lane with a silver locket wrapped in a handkerchief. The hedgerows of the old vicarage had seen everything, she always said; one had only to ask the right people in the right order.\n\nThat night she dreamed of the old vicarage with all its windows lit, and every window hiding something. She woke knowing the next step: confront the one person who had not been questioned — the jealous heir himself.\n\nDr. Samuel Reed brought the parish records, and together they found the gap: a name missing where a name should be, a date that did not fit. a silver locket was the key, Beatrice Nettle was certain; it unlocked a story someone had paid to keep shut.'}, {'n': 3, 'title': 'Questions at Dusk', 'text': "At dusk she walked to the old vicarage alone, turning a silver locket in her pocket. The answer, she felt, was close — as close as the church bell that began to toll, counting out the hours like clues.\n\nBack in the parlor, Beatrice Nettle laid out the evidence: the landlord's tale, the parish gap, the threatening note, the too-perfect description. Dr. Samuel Reed whistled. 'It's a noose,' they said, 'and the jealous heir tied it.'\n\nDr. Samuel Reed kept watch from the garden gate while Beatrice Nettle asked about a silver locket. the jealous heir claimed never to have seen it — but described it perfectly, down to the scratch on its side. Beatrice Nettle noted that, too."}, {'n': 4, 'title': 'The Storm Breaks', 'text': "The storm that had threatened the old vicarage all week broke at last, rattling the windows of the old vicarage. In the midst of it came a hammering at Beatrice Nettle's door: Dr. Samuel Reed, soaked, with news — the jealous heir had been seen digging near the old vicarage.\n\nBeatrice Nettle listened to the end, rain running off her cape. Justice, she said quietly, was not the same as punishment; but the truth belonged to everyone in the old vicarage, and it would be told.\n\nThey walked back through the storm with the evidence wrapped in oilcloth. Dr. Samuel Reed said nothing, but their silence was agreement. courage in quiet lives — even on the worst night, Beatrice Nettle thought, especially then."}, {'n': 5, 'title': 'The Reckoning', 'text': "That evening the kettle sang again in her cottage, and Beatrice Nettle wrote the last line in her journal: Truth told, justice done, neighbors mended. courage in quiet lives — I shall drink tea to that.\n\nThe constable did his duty, but Beatrice Nettle had already done hers: she had made the truth plain, so that no whisper could twist it. Dr. Samuel Reed squeezed her hand. 'Neatest case I ever saw,' they whispered.\n\nthe jealous heir's motive, when all heard it, drew more pity than anger — a lost inheritance, a sick child, a desperate choice. the old vicarage was stern, but the old vicarage was also kind; and kindness found a way to help where the law could only punish."}, {'n': 6, 'title': 'Quiet After', 'text': 'And if another mystery comes to the old vicarage — as mysteries do, like weather — Beatrice Nettle will be ready, kettle on, journal open. For courage in quiet lives, always, in the old vicarage and everywhere.\n\nA week later the old vicarage was itself again: the fete committee argued about bunting, the bakery smelled of scones, and a silver locket sat in its proper place, no longer a mystery but a keepsake with a story.\n\nthe jealous heir, from wherever the law had sent him, wrote a letter of thanks: for the truth, for the pity, for the chance to begin again. Beatrice Nettle read it twice and filed it with the case notes.'}]}

def word_count():
    return sum(len(c["text"].split()) for c in BOOK["chapters"])

def print_book(ch=None):
    print("=" * 64)
    print(BOOK["title"].upper(), "\nby", BOOK["author"], "-", BOOK["genre"])
    print("=" * 64)
    for c in BOOK["chapters"]:
        if ch and c["n"] != ch:
            continue
        print("\n\nCHAPTER %d: %s\n%s" % (c["n"], c["title"], "-" * 40))
        print(c["text"])
    print("\n[%d words, %d chapters — complete]" % (word_count(), len(BOOK["chapters"])))

def search(word):
    w = word.lower()
    for c in BOOK["chapters"]:
        for i, para in enumerate(c["text"].split("\n\n")):
            if w in para.lower():
                print("[ch %d, para %d] %s..." % (c["n"], i + 1, para[:160].replace("\n", " ")))

def write_html(path="book.html"):
    parts = ["<html><head><meta charset='utf-8'><title>%s</title></head><body>" % _h.escape(BOOK["title"])]
    parts.append("<h1>%s</h1><p><i>by %s — %s</i></p>" % (_h.escape(BOOK["title"]), _h.escape(BOOK["author"]), _h.escape(BOOK["genre"])))
    for c in BOOK["chapters"]:
        parts.append("<h2>Chapter %d: %s</h2>" % (c["n"], _h.escape(c["title"])))
        for para in c["text"].split("\n\n"):
            parts.append("<p>%s</p>" % _h.escape(para))
    parts.append("</body></html>")
    open(path, "w").write("\n".join(parts))
    print("wrote", path)

if __name__ == "__main__":
    a = sys.argv[1:]
    if a and a[0] == "html":
        write_html()
    elif len(a) >= 2 and a[0] == "search":
        search(a[1])
    elif a and a[0].isdigit():
        print_book(int(a[0]))
    else:
        print_book()

